"use client";

import { useApi } from "./useApi";
import { Category } from "@/types";
import { useQuery } from "@tanstack/react-query";

export const useCategories = () => {
  const api = useApi();

  return useQuery({
    queryKey: ["categories"],
    queryFn: async () => {
      const { data } = await api.get<Category[]>("/categories/");
      return data;
    },
  });
};
