"use client";

import { Product } from "@/types";
import { useCart } from "@/lib/hooks/useCart";
import { useRouter } from "next/navigation";
import Image from "next/image";
import { useState } from "react";

interface ProductsGridProps {
  isLoading: boolean;
  isError: boolean;
  products: Product[];
}

export default function ProductsGrid({
  products,
  isLoading,
  isError,
}: ProductsGridProps) {
  const { addToCart, isAddingToCart } = useCart();
  const router = useRouter();
  const [addingProductId, setAddingProductId] = useState<string | null>(null);

  const handleAddToCart = (product: Product) => {
    // If product has unit options, redirect to product page to select unit
    if (product.unitOptions && product.unitOptions.length > 0) {
      router.push(`/product/${product._id}`);
      return;
    }

    setAddingProductId(product._id);
    addToCart(
      {
        productId: product._id,
        quantity: 1,
        selectedUnit: undefined,
      },
      {
        onSettled: () => {
          setAddingProductId(null);
        },
      }
    );
  };

  if (isLoading) {
    return (
      <div className="py-20 flex items-center justify-center">
        <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-[#FFD700]"></div>
        <p className="text-[#B3B3B3] mt-4 ml-4">Loading products...</p>
      </div>
    );
  }

  if (isError) {
    return (
      <div className="py-20 flex flex-col items-center justify-center">
        <div className="text-5xl mb-4">⚠️</div>
        <p className="text-white font-semibold mt-4">Failed to load products</p>
        <p className="text-[#B3B3B3] text-sm mt-2">Please try again later</p>
      </div>
    );
  }

  if (products.length === 0) {
    return (
      <div className="py-20 flex flex-col items-center justify-center">
        <div className="text-5xl mb-4">🔍</div>
        <p className="text-white font-semibold mt-4">No products found</p>
        <p className="text-[#B3B3B3] text-sm mt-2">Try adjusting your filters</p>
      </div>
    );
  }

  return (
    <div className="grid grid-cols-2 gap-3">
      {products.map((product) => (
        <div
          key={product._id}
          className="bg-[#282828] rounded-3xl overflow-hidden mb-3 cursor-pointer hover:opacity-90 transition-opacity"
          onClick={() => router.push(`/product/${product._id}`)}
        >
          <div className="relative">
            <Image
              src={product.images[0]}
              alt={product.name}
              width={200}
              height={176}
              className="w-full h-44 object-cover bg-[#282828]"
              unoptimized
            />
          </div>

          <div className="p-3">
            <p className="text-[#B3B3B3] text-xs mb-1">{product.category}</p>
            <p className="text-white font-bold text-sm mb-2 line-clamp-2">
              {product.name}
            </p>

            <div className="flex items-center justify-between">
              {product.showPrice !== false && product.price && (
                <p className="text-[#FFD700] font-bold text-lg">
                  ${product.price.toFixed(2)}
                </p>
              )}

              <button
                className="bg-[#FFD700] rounded-full w-8 h-8 flex items-center justify-center hover:bg-[#FFE55C] transition-colors"
                onClick={(e) => {
                  e.stopPropagation();
                  handleAddToCart(product);
                }}
                disabled={isAddingToCart || addingProductId === product._id}
              >
                {isAddingToCart && addingProductId === product._id ? (
                  <div className="animate-spin rounded-full h-4 w-4 border-b-2 border-[#121212]"></div>
                ) : (
                  <span className="text-[#121212] text-lg font-bold">+</span>
                )}
              </button>
            </div>
          </div>
        </div>
      ))}
    </div>
  );
}
